/* ===== CONTROL CONTRACTUAL · AMBIENTACIÓN DE CONSTRUCCIÓN V1 ===== */
(()=>{
'use strict';
if(window.__CC_CONSTRUCTION_AMBIENCE_V1__)return;
window.__CC_CONSTRUCTION_AMBIENCE_V1__=true;

const CUTOUT='data:image/png;base64,';

function installStyle(){
  if(document.getElementById('ccConstructionAmbienceStyle'))return;
  const style=document.createElement('style');
  style.id='ccConstructionAmbienceStyle';
  style.textContent=`
body.cc-construction-ambience{position:relative;overflow-x:hidden;background:radial-gradient(circle at 12% 8%,rgba(94,127,99,.16),transparent 28%),radial-gradient(circle at 88% 18%,rgba(68,96,76,.12),transparent 24%),linear-gradient(rgba(82,108,87,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(82,108,87,.05) 1px,transparent 1px),#eef2ec!important;background-size:auto,auto,48px 48px,48px 48px,auto!important}
#ccConstructionScenery{position:fixed;inset:0;z-index:1;overflow:hidden;pointer-events:none;user-select:none}
#ccConstructionScenery .cc-blueprint-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(76,104,70,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(76,104,70,.055) 1px,transparent 1px),linear-gradient(rgba(76,104,70,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(76,104,70,.025) 1px,transparent 1px);background-size:48px 48px,48px 48px,12px 12px,12px 12px;mask-image:linear-gradient(to bottom,rgba(0,0,0,.85),rgba(0,0,0,.22) 58%,transparent);-webkit-mask-image:linear-gradient(to bottom,rgba(0,0,0,.85),rgba(0,0,0,.22) 58%,transparent)}
#ccConstructionScenery .cc-truss{position:absolute;left:28px;right:28px;top:0;height:32px;opacity:.44;border-top:5px solid #5f6d65;border-bottom:5px solid #5f6d65;background:repeating-linear-gradient(62deg,transparent 0 32px,rgba(68,82,73,.76) 33px 37px,transparent 38px 67px),repeating-linear-gradient(-62deg,transparent 0 32px,rgba(68,82,73,.56) 33px 37px,transparent 38px 67px);filter:drop-shadow(0 6px 9px rgba(24,38,28,.20))}
#ccConstructionScenery .cc-column{position:absolute;top:0;bottom:0;width:26px;opacity:.38;background:linear-gradient(90deg,#46534b 0 14%,#9eaaa2 15% 27%,#59675e 28% 72%,#b3bbb5 73% 85%,#455149 86%);box-shadow:0 0 0 1px rgba(39,55,44,.34),5px 0 16px rgba(32,48,36,.16)}
#ccConstructionScenery .cc-column:before{content:"";position:absolute;inset:7px 5px;background:radial-gradient(circle,#24332a 0 2px,transparent 2.6px) center top/12px 42px repeat-y}
#ccConstructionScenery .cc-column-left{left:8px}.cc-column-right{right:8px;transform:scaleX(-1)}
#ccConstructionScenery .cc-crane{position:absolute;right:7%;top:10%;width:260px;height:190px;opacity:.16}
#ccConstructionScenery .cc-crane:before{content:"";position:absolute;right:34px;top:0;width:10px;height:188px;background:linear-gradient(90deg,#425148,#8a978f 48%,#425148 52%);clip-path:polygon(20% 0,80% 0,100% 100%,0 100%)}
#ccConstructionScenery .cc-crane:after{content:"";position:absolute;right:32px;top:2px;width:224px;height:9px;background:#526158;box-shadow:0 13px 0 -3px rgba(82,97,88,.72);transform-origin:right center;transform:skewX(-20deg)}
#ccConstructionScenery .cc-hook{position:absolute;right:205px;top:13px;width:2px;height:92px;background:#526158}.cc-hook:after{content:"";position:absolute;left:-5px;bottom:-11px;width:10px;height:13px;border:2px solid #526158;border-top:0;border-radius:0 0 8px 8px}
#ccConstructionScenery .cc-site-line{position:absolute;left:4%;right:4%;bottom:0;height:104px;opacity:.17;background:linear-gradient(to top,#536258 0 7px,transparent 7px),repeating-linear-gradient(90deg,transparent 0 72px,#5c6d62 73px 79px,transparent 80px 148px)}
#ccConstructionScenery .cc-site-line:before{content:"";position:absolute;left:0;right:0;bottom:70px;height:8px;background:#607067;box-shadow:0 18px 0 -2px rgba(96,112,103,.70)}
#app,.cp-login-shell,.shell,#ccEngineerChat,#ccEngineerChatLaunch{position:relative;z-index:2}
.cp-login-shell{isolation:isolate}
.cp-login-brand{position:relative;overflow:hidden!important}
.cp-login-brand>*{position:relative;z-index:1}
.cp-login-brand:before{content:"";position:absolute;inset:7% 7% 9%;z-index:0;opacity:.16;background:linear-gradient(90deg,transparent 0 12%,rgba(255,255,255,.52) 12% 13%,transparent 13% 79%,rgba(255,255,255,.46) 79% 80%,transparent 80%),repeating-linear-gradient(58deg,transparent 0 72px,rgba(255,255,255,.40) 73px 76px,transparent 77px 145px),repeating-linear-gradient(-58deg,transparent 0 72px,rgba(255,255,255,.26) 73px 76px,transparent 77px 145px);border-top:6px solid rgba(255,255,255,.40);border-bottom:6px solid rgba(255,255,255,.30)}
.cp-login-brand:after{content:"PLANO ESTRUCTURAL · CONTROL DE OBRA";position:absolute;left:8%;bottom:7%;font:800 9px/1.2 Inter,system-ui,sans-serif;letter-spacing:.18em;color:rgba(255,255,255,.54)}
.dashboard-hero{isolation:isolate}
.dashboard-hero:after{content:"";position:absolute!important;z-index:0!important;left:4%!important;right:4%!important;bottom:0!important;height:18px!important;border-radius:3px 3px 7px 7px!important;background:linear-gradient(180deg,#8d9b92 0 18%,#4d5e53 19% 39%,#718078 40% 60%,#4b5a50 61% 82%,#9aa69f 83%)!important;box-shadow:0 -1px 0 rgba(255,255,255,.18),0 8px 18px rgba(23,38,28,.18)!important;opacity:.52!important}
.dashboard-hero .hero-copy,.dashboard-hero .hero-side{position:relative;z-index:1}
.topbar{isolation:isolate}
.topbar:after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:3px;background:linear-gradient(90deg,transparent,#6f7d74 8%,#aab4ae 50%,#6f7d74 92%,transparent);opacity:.32;pointer-events:none}
.panel,.kpi,.card,.aside-card,.followup-panel,.quick-panel{background-image:radial-gradient(circle at 12px 12px,rgba(76,95,81,.20) 0 2px,transparent 2.8px),radial-gradient(circle at calc(100% - 12px) 12px,rgba(76,95,81,.18) 0 2px,transparent 2.8px)!important;background-repeat:no-repeat!important}
#ccEngineerChatLaunch .cc-halu-seated-image{background:transparent!important;filter:drop-shadow(0 10px 7px rgba(17,31,21,.28));image-rendering:auto}
@media(max-width:900px){#ccConstructionScenery .cc-column,#ccConstructionScenery .cc-truss{opacity:.12}#ccConstructionScenery .cc-crane{opacity:.06;right:-80px}.cp-login-brand:after{display:none}}
@media(max-width:620px){#ccConstructionScenery .cc-column,#ccConstructionScenery .cc-truss,#ccConstructionScenery .cc-crane{display:none}#ccConstructionScenery .cc-blueprint-grid{opacity:.55}.dashboard-hero:after{height:12px!important}}
@media(prefers-reduced-motion:reduce){#ccConstructionScenery *{animation:none!important}}
@media print{#ccConstructionScenery{display:none!important}.panel,.kpi,.card{background-image:none!important}}
`;
  document.head.appendChild(style);
}

function installScenery(){
  if(document.getElementById('ccConstructionScenery'))return;
  const scenery=document.createElement('div');
  scenery.id='ccConstructionScenery';
  scenery.setAttribute('aria-hidden','true');
  scenery.innerHTML='<i class="cc-blueprint-grid"></i><i class="cc-truss"></i><i class="cc-column cc-column-left"></i><i class="cc-column cc-column-right"></i><i class="cc-crane"><i class="cc-hook"></i></i><i class="cc-site-line"></i>';
  document.body.prepend(scenery);
}

function refreshCutout(){
  document.querySelectorAll('#ccEngineerChatLaunch .cc-halu-seated-image').forEach(img=>{
    if(!img.src.includes('halu-engineer-seated-cutout-v2.png'))img.src=CUTOUT;
    img.removeAttribute('loading');
  });
}

function install(){
  installStyle();
  installScenery();
  document.body.classList.add('cc-construction-ambience');
  refreshCutout();
  new MutationObserver(refreshCutout).observe(document.body,{subtree:true,childList:true});
}

if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
